import itertools
def fewest(a,av):
    best=None
    for f in range(min(av[0],a//50),-1,-1):
        r=a-50*f
        for t in range(min(av[1],r//20),-1,-1):
            rr=r-20*t; c=rr//10
            if rr%10 or c>av[2]: continue
            if best is None or f+t+c<sum(best): best=(f,t,c)
    return best
def passes(n,mode):
    F,T,C=n; out=[]
    while F+T+C>0:
        room=4; f=min(room,F); room-=f
        if mode=='P2': room=4
        t=min(room,T)
        if mode!='P1': room-=t
        c=min(4 if mode=='P3' else room,C)
        out.append((f,t,c)); F-=f;T-=t;C-=c
    return out
tot={};bad={}
for st in itertools.product(range(6),repeat=3):
  for j in [None,0,1,2]:
    av=tuple(0 if i==j else st[i] for i in range(3))
    for a in range(10,230,10):
      n=fewest(a,av)
      if not n: continue
      for m in ['P1','P2','P3']:
        tot[m]=tot.get(m,0)+1
        if any(sum(p)>4 for p in passes(n,m)): bad[m]=bad.get(m,0)+1
print(tot,bad)
full=(5,5,5)
for m in ['P1','P2','P3']:
  print(m,[a for a in range(10,230,10) if any(sum(p)>4 for p in passes(fewest(a,full),m))])
